/* A pinned star: the section is two windows tall and its stage sticks for the length of one.
   Eight hairline rays with numbered tips turn half a turn with the scroll (the numbers stay
   upright), the first heading slides up out of its masks while the second rises in, and a
   dark copy of the stage fades over the light one, so the page turns black on the way into
   the dark sections that follow. */

@property --kononenkogroup-principles-turn {
  syntax: "<angle>";
  inherits: true;
  initial-value: 0deg;
}

.kononenkogroup-principles {
  view-timeline-name: --kononenkogroup-principles;
  --kononenkogroup-principles-r: min(42.5svh, 44vw);
}

.kononenkogroup-principles-star {
  position: absolute;
  inset: 0;
  transform: rotate(var(--kononenkogroup-principles-turn));
}

.kononenkogroup-principles-ray {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0;
  height: 0;
  transform: rotate(var(--kononenkogroup-principles-angle));
}

.kononenkogroup-principles-line {
  position: absolute;
  left: -0.5px;
  width: 1px;
  bottom: calc(var(--kononenkogroup-principles-r) * 0.3);
  height: calc(var(--kononenkogroup-principles-r) * 0.64);
  background: linear-gradient(to top, transparent, color-mix(in oklab, var(--foreground) 30%, transparent));
}

.kononenkogroup-principles-label {
  position: absolute;
  left: 0;
  top: calc(var(--kononenkogroup-principles-r) * -1);
  transform: translate(-50%, -50%)
    rotate(calc(-1 * (var(--kononenkogroup-principles-angle) + var(--kononenkogroup-principles-turn))));
}

.kononenkogroup-principles-mask {
  display: block;
  overflow: clip;
  padding-block: 0.12em 0.2em;
  margin-block: -0.12em -0.2em;
}

.kononenkogroup-principles-word {
  display: block;
}

/* the dark copy only exists where it can be animated */
.kononenkogroup-principles-night {
  display: none;
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .kononenkogroup-principles-stage {
      animation: kononenkogroup-principles-spin linear both;
      animation-timeline: --kononenkogroup-principles;
      animation-range: cover 0% cover 100%;
    }

    /* the two headings share one place; without animation they simply stack */
    .kononenkogroup-principles-second {
      position: absolute;
      inset: 0;
    }

    .kononenkogroup-principles-first .kononenkogroup-principles-word {
      animation: kononenkogroup-principles-out linear both;
      animation-timeline: --kononenkogroup-principles;
      animation-range: contain 12% contain 42%;
    }

    .kononenkogroup-principles-second .kononenkogroup-principles-word {
      animation: kononenkogroup-principles-in cubic-bezier(0.17, 0.84, 0.44, 1) both;
      animation-timeline: --kononenkogroup-principles;
      animation-range: contain 48% contain 78%;
    }

    .kononenkogroup-principles-night {
      display: block;
      animation: kononenkogroup-principles-dusk linear both;
      animation-timeline: --kononenkogroup-principles;
      animation-range: contain 18% contain 40%;
    }
  }
}

@keyframes kononenkogroup-principles-spin {
  from {
    --kononenkogroup-principles-turn: 0deg;
  }
  to {
    --kononenkogroup-principles-turn: -180deg;
  }
}

@keyframes kononenkogroup-principles-out {
  from {
    transform: none;
  }
  to {
    transform: translateY(calc(-100% - 0.5em));
  }
}

@keyframes kononenkogroup-principles-in {
  from {
    transform: translateY(calc(100% + 0.5em));
  }
  to {
    transform: none;
  }
}

@keyframes kononenkogroup-principles-dusk {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

import type { CSSProperties } from "react";
import { cn } from "@foundry/foundry-utils";
import "./kononenkogroup-principles.css";

export interface KononenkogroupPrinciplesProps {
  /** the labels at the tips of the rays, clockwise from the top (eight on the original) */
  rays: string[];
  /** the heading shown first, one item per line */
  first: string[];
  /** the heading that replaces it halfway through, one item per line */
  second: string[];
  /** hide the whole section below 1024px, as the original does */
  desktopOnly?: boolean;
  className?: string;
}

function Heading({ lines, which }: { lines: string[]; which: "first" | "second" }) {
  return (
    <span className={cn(`kononenkogroup-principles-${which}`, "flex flex-col justify-center")}>
      {lines.map((line, i) => (
        <span key={i} className="kononenkogroup-principles-mask">
          <span className="kononenkogroup-principles-word">{line}</span>
        </span>
      ))}
    </span>
  );
}

function Stage({ rays, first, second, copy }: Omit<KononenkogroupPrinciplesProps, "desktopOnly" | "className"> & { copy?: boolean }) {
  const Tag = copy ? "p" : "h2";
  return (
    <div className="kononenkogroup-principles-stage absolute inset-0">
      <div className="kononenkogroup-principles-star" aria-hidden>
        {rays.map((ray, i) => (
          <span
            key={i}
            className="kononenkogroup-principles-ray"
            style={{ "--kononenkogroup-principles-angle": `${(360 / rays.length) * i}deg` } as CSSProperties}
          >
            <span className="kononenkogroup-principles-line" />
            <span className="kononenkogroup-principles-label font-sans text-[2.4vw] leading-none lg:text-[max(9px,0.625vw)]">{ray}</span>
          </span>
        ))}
      </div>
      <div className="absolute inset-0 flex items-center justify-center">
        <Tag className="relative text-center font-sans text-[10.67vw] leading-[0.85] tracking-[-0.045em] lg:text-[4.17vw] lg:leading-[0.875]">
          <Heading lines={first} which="first" />
          <Heading lines={second} which="second" />
        </Tag>
      </div>
    </div>
  );
}

/**
 * A pinned interlude two windows tall: a star of eight hairline rays with numbered tips around
 * a centred two-line heading. While it is pinned the star turns half a turn, the heading slides
 * up and out as a second one rises into its place, and the stage fades to black, leading into
 * dark sections. Desktop only by default, like the original.
 */
export function KononenkogroupPrinciples({ rays, first, second, desktopOnly = true, className }: KononenkogroupPrinciplesProps) {
  return (
    <section className={cn("kononenkogroup-principles relative h-[200svh]", desktopOnly && "hidden lg:block", className)}>
      <div className="sticky top-0 h-svh overflow-clip bg-background text-foreground">
        <Stage rays={rays} first={first} second={second} />
        <div aria-hidden className="kononenkogroup-principles-night dark absolute inset-0 bg-background text-foreground">
          <Stage rays={rays} first={first} second={second} copy />
        </div>
      </div>
    </section>
  );
}
